import JSZip from "jszip";
import { adminFetch } from "./session";

// ---------------------------------------------------------------------------
// Signed upload to Cloudinary. The signature itself is generated by the API
// (POST /media/cloudinary-signature), not here — the actual Cloudinary API
// secret lives only in the API's database (Admin → Cloudinary Settings) or
// its own .env, never in this frontend project, so there's nothing sensitive
// for this file to hold. Used from Server Actions only (adminFetch needs the
// admin's session cookie, which only exists in a server context).
// ---------------------------------------------------------------------------

export class CloudinaryConfigError extends Error {}
export class CloudinaryUploadValidationError extends Error {}

// Every image/video an admin uploads goes through here, so this is the one
// choke point to enforce file-type and size limits — without it, any
// signed-in EDITOR could upload an arbitrarily large file (storage-cost
// abuse) or an SVG containing an inline <script> (Cloudinary's "auto"
// resource type accepts SVG as an image; browsers execute script inside an
// SVG rendered directly, e.g. in an <img>/<object> tag or if opened
// standalone — a stored-XSS vector). image/svg+xml is deliberately left out
// of the allow-list for that reason.
const ALLOWED_MIME_TYPES = new Set([
  "image/jpeg",
  "image/png",
  "image/webp",
  "image/gif",
  "image/avif",
  "video/mp4",
  "video/webm",
  "video/quicktime",
]);
const MAX_IMAGE_BYTES = 10 * 1024 * 1024; // 10MB
const MAX_VIDEO_BYTES = 200 * 1024 * 1024; // 200MB

function assertUploadAllowed(file: File) {
  if (!ALLOWED_MIME_TYPES.has(file.type)) {
    throw new CloudinaryUploadValidationError(
      `Unsupported file type "${file.type || "unknown"}". Allowed: JPG, PNG, WEBP, GIF, AVIF, MP4, WEBM, MOV.`,
    );
  }
  const maxBytes = file.type.startsWith("video/") ? MAX_VIDEO_BYTES : MAX_IMAGE_BYTES;
  if (file.size > maxBytes) {
    throw new CloudinaryUploadValidationError(
      `File is too large (${Math.round(file.size / 1024 / 1024)}MB). Max is ${Math.round(maxBytes / 1024 / 1024)}MB.`,
    );
  }
}

/**
 * Uploads a File (from a <form>'s FormData) to Cloudinary and returns its
 * secure URL. Returns null if `file` is empty/absent, so callers can treat
 * "no file chosen" as "leave the existing image alone."
 */
export async function uploadToCloudinary(
  file: File | null | undefined,
  folder = "sterling-vance",
): Promise<string | null> {
  if (!file || file.size === 0) return null;

  assertUploadAllowed(file);

  const sigRes = await adminFetch("/media/cloudinary-signature", {
    method: "POST",
    body: JSON.stringify({ folder }),
  });
  if (!sigRes.ok) {
    const body = await sigRes.json().catch(() => null);
    throw new CloudinaryConfigError(
      body?.message ||
        "Cloudinary isn't configured yet — set it up in Admin → Cloudinary Settings.",
    );
  }
  const { cloudName, apiKey, timestamp, signature } = await sigRes.json();

  // Cloudinary rejects "auto" for resource_type combined with an
  // allowed_formats restriction on some plans, so the resource type is
  // pinned explicitly from the validated mime type instead of trusting
  // Cloudinary's own sniffing — belt-and-suspenders with the allow-list
  // check above.
  const resourceType = file.type.startsWith("video/") ? "video" : "image";

  const form = new FormData();
  form.append("file", file);
  form.append("api_key", apiKey);
  form.append("timestamp", String(timestamp));
  form.append("signature", signature);
  form.append("folder", folder);

  const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/${resourceType}/upload`, {
    method: "POST",
    body: form,
  });

  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`Cloudinary upload failed (${res.status}): ${text}`);
  }

  const data = await res.json();
  return data.secure_url as string;
}

const ZIP_FRAME_EXT = /\.(jpe?g|png|webp)$/i;
const MAX_ZIP_BYTES = 300 * 1024 * 1024; // 300MB of source frames — generous for a 48fps clip before downsampling

// Natural sort so "frame_2.jpg" sorts before "frame_10.jpg" — a plain
// string sort would put "frame_10" first (since "1" < "2" as characters),
// silently scrambling playback order for any sequence past 9 frames, which
// is virtually every real frame export.
function naturalCompare(a: string, b: string): number {
  const chunk = (s: string) => s.match(/(\d+|\D+)/g) ?? [s];
  const ac = chunk(a);
  const bc = chunk(b);
  for (let i = 0; i < Math.max(ac.length, bc.length); i++) {
    const x = ac[i] ?? "";
    const y = bc[i] ?? "";
    if (x === y) continue;
    const nx = Number(x);
    const ny = Number(y);
    if (!Number.isNaN(nx) && !Number.isNaN(ny)) return nx - ny;
    return x < y ? -1 : 1;
  }
  return 0;
}

/**
 * Unpacks a zip of sequential frame images (e.g. an exported 48fps clip)
 * and uploads an evenly-downsampled subset of them to Cloudinary, in
 * playback order — for the admin-uploaded scroll-driven landing animation
 * (Admin → Landing Animation). A 48fps source has far more frames than a
 * smooth scroll-scrub actually needs (and far more than is reasonable to
 * ship to every visitor's browser), so this always caps the result at
 * `maxFrames`, picking frames evenly spaced across the full sequence rather
 * than just the first N — that keeps the full motion, just at a lighter
 * sampling rate, instead of only playing back its first second.
 */
export async function uploadFrameZipToCloudinary(
  file: File | null | undefined,
  folder: string,
  maxFrames = 28,
): Promise<string[]> {
  if (!file || file.size === 0) return [];
  if (file.type !== "application/zip" && file.type !== "application/x-zip-compressed" && !file.name.toLowerCase().endsWith(".zip")) {
    throw new CloudinaryUploadValidationError('That file isn\'t a .zip. Export your frames as a single .zip of image files (JPG/PNG/WEBP) and upload that.');
  }
  if (file.size > MAX_ZIP_BYTES) {
    throw new CloudinaryUploadValidationError(`Zip is too large (${Math.round(file.size / 1024 / 1024)}MB). Max is ${Math.round(MAX_ZIP_BYTES / 1024 / 1024)}MB of source frames.`);
  }

  const zip = await JSZip.loadAsync(await file.arrayBuffer());
  const entries = Object.values(zip.files)
    .filter((f) => !f.dir && ZIP_FRAME_EXT.test(f.name) && !f.name.includes("__MACOSX") && !f.name.split("/").pop()!.startsWith("."))
    .sort((a, b) => naturalCompare(a.name, b.name));

  if (entries.length === 0) {
    throw new CloudinaryUploadValidationError("No JPG/PNG/WEBP frame images found inside that zip.");
  }

  // Evenly-spaced downsample: e.g. 240 source frames -> 28 keeps the whole
  // motion arc, just sampled more coarsely, rather than truncating to the
  // clip's first ~3 seconds.
  const picked =
    entries.length <= maxFrames
      ? entries
      : Array.from({ length: maxFrames }, (_, i) => entries[Math.round((i * (entries.length - 1)) / (maxFrames - 1))]);

  const sigRes = await adminFetch("/media/cloudinary-signature", {
    method: "POST",
    body: JSON.stringify({ folder }),
  });
  if (!sigRes.ok) {
    const body = await sigRes.json().catch(() => null);
    throw new CloudinaryConfigError(
      body?.message || "Cloudinary isn't configured yet — set it up in Admin → Cloudinary Settings.",
    );
  }
  const { cloudName, apiKey, timestamp, signature } = await sigRes.json();

  // Uploaded with limited concurrency (not all-at-once, not one-at-a-time)
  // — dozens of simultaneous multipart uploads from one server action risk
  // tripping Cloudinary's rate limits or the host's own outbound connection
  // limits, while a strict one-at-a-time queue makes ~28 frames noticeably
  // slower to process than it needs to be.
  const CONCURRENCY = 4;
  const urls: string[] = new Array(picked.length);
  let cursor = 0;
  async function worker() {
    while (cursor < picked.length) {
      const i = cursor++;
      const entry = picked[i];
      const blob = await entry.async("blob");
      const ext = entry.name.split(".").pop()!.toLowerCase();
      const mime = ext === "png" ? "image/png" : ext === "webp" ? "image/webp" : "image/jpeg";
      const form = new FormData();
      form.append("file", new File([blob], entry.name, { type: mime }));
      form.append("api_key", apiKey);
      form.append("timestamp", String(timestamp));
      form.append("signature", signature);
      form.append("folder", folder);
      const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, { method: "POST", body: form });
      if (!res.ok) {
        const text = await res.text().catch(() => "");
        throw new Error(`Frame ${i + 1}/${picked.length} upload failed (${res.status}): ${text}`);
      }
      const data = await res.json();
      urls[i] = data.secure_url as string;
    }
  }
  await Promise.all(Array.from({ length: Math.min(CONCURRENCY, picked.length) }, worker));

  return urls;
}
